import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check for correlation with outcome using Welch's t-test
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        group0 = feats.x[feats.y == 0, i]
        group1 = feats.x[feats.y == 1, i]
        if len(group0) > 0 and len(group1) > 0:
            t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
            mean_diff = np.mean(group1) - np.mean(group0)
            effects.append((fid, abs(mean_diff), abs(t_stat), p_val))

    # Sort by effect size and p-value
    effects.sort(key=lambda x: (-x[1], x[3]))

    # Check for stratified consistency
    strata_consistent = []
    strata_effects = {}

    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        strata_effects[fid] = []
        for stratum in set(feats.stratum):
            mask = [s == stratum for s in feats.stratum]
            y_stratum = feats.y[mask]
            x_stratum = feats.x[mask, i]
            if len(y_stratum) > 1 and len(np.unique(y_stratum)) == 2:
                group0 = x_stratum[y_stratum == 0]
                group1 = x_stratum[y_stratum == 1]
                if len(group0) > 0 and len(group1) > 0:
                    t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
                    strata_effects[fid].append(abs(t_stat))

    # Filter features consistent across strata
    for fid, _, _, p_val in effects:
        if len(strata_effects[fid]) > 0:
            avg_effect = np.mean(strata_effects[fid])
            if avg_effect > 1.0 and p_val < 0.1:
                strata_consistent.append(fid)

    # Select top drivers based on effect size and consistency
    drivers = strata_consistent[:MAX_DRIVERS]

    # For products, look for correlated pairs with |r| >= 0.6
    products = []
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr
                if abs(corr) >= 0.7:
                    products.append((fid1, fid2))

    # Build columns list (all features with strong effects)
    columns = [f for f in feats.ids if f in strata_consistent or f in [p[0] for p in products] or f in [p[1] for p in products]]

    # Limit total features to prevent overfitting
    if len(columns) > 12:
        # Take only top 12 features by effect size
        effect_dict = dict([(fid, effect_size) for fid, effect_size, _, _ in effects])
        columns.sort(key=lambda f: effect_dict.get(f, 0), reverse=True)
        columns = columns[:12]

    # Loadings: weight by effect strength
    loadings = {}
    for fid, effect_size, _, _ in effects:
        if fid in columns:
            loadings[fid] = effect_size

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
